INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.54.0',
  '2026-07-29',
  'Календарь — новая страница: все данные по дням со слоями и пересечениями',
  E'Новая страница «Calendar» 📅: сетка месяца, на которую подключаются слои — несколько трекеров сразу (точки цветов категорий; дни, где отмечены ВСЕ выбранные трекеры, подсвечены зелёной рамкой — пересечения привычек видны сразу), напоминания (повторы разложены по дням), дневник, задачи со сроком (просроченные краснеют), чек-листы (история повторяющихся списков и дедлайны), еда (ккал против цели) и AI-расписания. Клик по дню — всё содержимое дня со ссылками на страницы. Выбор слоёв запоминается на сервере.',
  E'Фазы 1+2 плана. Бэкенд: GET /calendar?from&to&tz_off — агрегат одним запросом (до 62 дней): ListCategories+MarksInRange (трекеры, вкл. шаринг), CalendarReminders (раскладка повторов по дням диапазона: daily/weekly по days_mask (бит 0 = Пн)/monthly с клампом 31-го/yearly; interval — только день next_fire_at, иначе спам), CalendarDiary/Deadlines/AIRuns (группировка по дню в таймзоне клиента через FixedZone(tz_off) с запасом ±14ч по краям), CalendarTasks (done = status_kind=done — колонки done в tasks НЕТ), CalendarCheckerDays (снапшоты + имя рута), CalendarFood (SUM(items.calories) по дням + действующая цель из food_goals по date_from/date_to). Prefs: таблица calendar_prefs (JSONB как есть, кап 16КБ), GET/PUT /calendar/prefs. Страница calendar в PagesRegistry (all) + guardedPages. Фронт apps/calendar: сетка Пн-первая (42 клетки с хвостами), кэш по диапазону, панель «Слои» (мультивыбор трекеров + 6 тумблеров, автосохранение с дебаунсом 600мс; trackers=null — все), точки/эмодзи до 4 + «+n», подсветка полного пересечения (все выбранные ≥2 отмечены), иконки источников с состояниями (просрочено/частично/перебор ккал), модалка дня по секциям со ссылками. Help-секция. E2E: пересечение 29-го (2 трекера), daily-напоминание разложено на 31 день, дневник/задача/снапшот/дедлайн/еда с целью/ai — все сканы строк проверены.'
);
